  list: { type: "Component", maturity: "experimental", overview: "Reorder an ordered set of product items.", use: "Use when order itself matters to users.", avoid: "Use Table for columnar comparison.", anatomy: "Ordered list, item details, drag target and move controls.", variants: "Default and disabled move limits", sizes: "Content driven", accessibility: "Move up/down buttons provide a keyboard path alongside pointer drag.", api: "List accepts items, onItemsChange and optional renderItem." },
