  "page-header": { type: "Pattern", maturity: "candidate", overview: "A consistent page title, supporting description, and nearby actions.", use: "Use at the top of a product page.", avoid: "Avoid inside a small card or repeated list item.", anatomy: "PageHeader.Content, Title, Description, Actions.", variants: "Responsive stacked and row layouts", sizes: "Content driven; actions wrap on narrow screens", accessibility: "Title is an h1. Actions remain native interactive controls.", api: "Compound PageHeader parts accept native element props." },
  "state-panel": { type: "Pattern", maturity: "candidate", overview: "Explain a page or region state and offer a next step.", use: "Use for empty, success, warning or error states that need a clear recovery action.", avoid: "Use StatusNotice for short inline feedback. StatusNotice serves the Alert use case; EmptyState serves the Empty use case without duplicate aliases.", anatomy: "Optional icon, heading, description and action.", variants: "neutral, success, warning, destructive", sizes: "Minimum 208px height", accessibility: "Choose h1 or h2 for the region hierarchy; icon is decorative and tone is conveyed in text.", api: "StatePanelProps adds title, description, action, icon, tone and headingLevel." },
