  "filter-toolbar": { type: "Pattern", maturity: "candidate", overview: "Combine search, sort and pressed filters above a result set.", use: "Use when a list has multiple ways to narrow or order results.", avoid: "Do not hide essential controls behind an unlabeled icon.", anatomy: "Toolbar, Group, pressed Toggle and adjacent result count/list; compose SearchField or Select as needed.", variants: "Responsive stack and row", sizes: "Content driven", accessibility: "Each filter toggle exposes aria-pressed; search and sort need visible or programmatic labels; results need an announced count.", api: "FilterToolbar and FilterGroup accept div props; FilterToggle accepts Button props and pressed." },
  "empty-state": { type: "Pattern", maturity: "experimental", overview: "Explains why a data region is empty and offers a next step; covers the Empty use case.", use: "Use for first use or filtered zero results.", avoid: "Do not present a creation action if users lack permission.", anatomy: "Optional decorative icon, title, explanation and optional action.", variants: "One dashed card", sizes: "Responsive width", accessibility: "The title remains text; the icon is decorative; the action's behavior is owned by the app.", api: "title, description?, icon?, action?, native div props." },
  "form-section": { type: "Pattern", maturity: "experimental", overview: "Groups related settings fields with a section title and guidance.", use: "Use for coherent settings or profile groups.", avoid: "Use Field for one input with label, help and error; FormSection groups multiple related fields.", anatomy: "Section heading, description and two or more related labelled fields.", variants: "Stacked below 40rem of section width; two columns in wider sections", sizes: "Content driven", accessibility: "Fields still need their own labels; section title is an h2.", api: "title, description?, children, native section props." },
