  "stat-card": { type: "Pattern", maturity: "experimental", overview: "One summary metric with label and optional context.", use: "Use for compact dashboard summaries.", avoid: "Do not hide units or meaning in color alone.", anatomy: "Label, value, optional detail.", variants: "One card surface", sizes: "Content driven", accessibility: "Label and detail describe the value in text.", api: "label, value, detail?, native div props." },
  "settings-section": { type: "Block", maturity: "experimental", overview: "A ready-to-use settings region combining FormSection and Card.", use: "Use for grouped settings fields in a settings page.", avoid: "Avoid where the card would create unnecessary nesting.", anatomy: "Section heading, description, card, related fields and app-owned save action.", variants: "One composed layout", sizes: "Content driven", accessibility: "Children remain responsible for field labels and result status.", api: "title, description?, children." },
