/** Shared installation/execution rule for every interactive source. */
export const motionRule = "Visual transitions use Motion and --lm-motion-* tokens. The registry installs motion and its helper where needed. Reduced motion removes movement; repeating decoration also pauses offscreen and in hidden documents. CSS defines static states. No global provider is required.";
